import{_ as i,l as o,o as e,c as s,v as t,p as l,x as n,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"资金约束与 CAPM 偏离","description":"","frontmatter":{"title":"资金约束与 CAPM 偏离","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/funding-constraints-capm.md","filePath":"econ/funding-constraints-capm.md","lastUpdated":1789023840000}'),m={name:"econ/funding-constraints-capm.md"};function B(E,a,h,u,A,_){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="资金约束与-capm-偏离" tabindex="-1">资金约束与 CAPM 偏离 <a class="header-anchor" href="#资金约束与-capm-偏离" aria-label="Permalink to &quot;资金约束与 CAPM 偏离&quot;">​</a></h1><div class="epigraph"><p>切点加总要求人人能按同一利率自由持有市场；杠杆与保证金一绑紧，受约束者的有效风险厌恶改，beta 定价出现截距与斜率扭曲。</p><footer>—— 据 Black, Capital Market Equilibrium with Restricted Borrowing, Journal of Business 1972；对照 Brunnermeier–Pedersen；Frazzini and Pedersen, Betting Against Beta, JFE 2014 的理论部分</footer></div><p><a href="/econ/leverage-cycle">上一课</a>给出内生杠杆谁在约束上。<a href="/econ/capm-theory">CAPM 作为均衡</a> 给出无约束时 \\(m\\) 对 \\(R_m\\) 线性。本课缺口是两者相减：资金约束如何让市场组合不再对所有人有效，截面上出现「低 beta 溢价过高、高 beta 溢价不足」一类<strong>理论</strong>偏离。不跑 Betting Against Beta 的组合表——实证在 <a href="/quant/capm">/quant/capm</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sharpe–Lintner：自由借贷，每人同一切点。Black（1972）已经关掉无风险借贷，切点换成零 beta，线性仍在。更紧的约束是：一部分人不能加杠杆（或保证金把有效借贷利率推高）。他们用高 beta 资产当杠杆替代，把高 beta 价格抬高、预期回报压低；受约束的中介若必须持有高 beta 库存，方向可以再变。Frazzini–Pedersen 的理论节：杠杆约束使证券的 alpha 与 beta 负相关——这是均衡陈述，不是排序组合。</p><p>缺口是：CAPM 的失败可以来自加总假设被资金约束破坏，而不必来自偏好不是均值方差，也不必来自无效。本栏只写这一许可，不宣布数据选择了它。</p><p><span class="marginnote">Black 1972 是借款限制。Gârleanu–Pedersen 把保证金差写成跨资产的资金溢价。本课用「约束破坏共同切点」一句话收束，不展开所有变体。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无约束者仍沿有效前沿；约束者的需求扭曲。出清的市场组合是两类需求之和，因而不再对约束者有效，对无约束者也不必等于切点。\\(m\\) 不再只是 \\(a-b R_m\\)，还含约束乘子对哪些资产占用资金的暴露。资金密集（高保证金、高 beta）的资产，乘子进入定价，期望超额偏离 \\(\\beta\\lambda_m\\)。</p>',9)),(e(),l(c,null,{default:n(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAPM%5B%22%E5%85%B1%E5%90%8C%E5%88%87%E7%82%B9%20%3D%20%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20LIN%5B%22E%5BRe%5D%20%3D%20%CE%B2%20%CE%BBm%22%5D%0A%20%20BIND%5B%22%E6%9D%A0%E6%9D%86%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SPLIT%5B%22%E9%9C%80%E6%B1%82%E5%88%86%E5%8F%89%22%5D%0A%20%20SPLIT%20--%3E%20DEV%5B%22%E5%B8%82%E5%9C%BA%E4%B8%8D%E5%86%8D%E5%AF%B9%E4%BA%BA%E4%BA%BA%E6%9C%89%E6%95%88%22%5D%0A%20%20DEV%20--%3E%20ALPHA%5B%22%CE%B1%20%E4%B8%8E%E8%B5%84%E9%87%91%E6%9A%B4%E9%9C%B2%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与中介定价：He–Krishnamurthy 改的是风险价格水平（所有风险一起变贵）；本课改的是<strong>相对</strong>定价（哪些资产更占资金）。BP 螺旋让约束时变，于是偏离时变。不要把这些写成三个因子模型——因子是量化栏的投影。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是替代。不能借钱的人买高 beta，等于自制杠杆；高 beta 被买贵。能借钱的人若资本充足，会做反向（买低 beta、做空高 beta）把偏离压回去——但他们自己也可能受保证金约束，套利限制接住这条反向。Shleifer–Vishny 的套利限制在行为课序；这里的限制是资金，不必非理性。信息对称、信念同质，只要约束在，偏离就可以均衡存在。</p><p>Roll 批评仍在：真正市场不可观测。约束下「市场指数是否有效」更不是 CAPM 的终审。本课不审指数。</p><p><span class="marginnote">低 beta 的理论溢价高于 CAPM 线，是约束均衡的可能形状。是否出现在平均收益表上，换栏。本课禁止贴出 BAB 的 t 统计量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课离开「谁受约束」转到被追逐的对象：安全资产为什么能以低于 FTAP 无风险的收益率交易——便利收益。资金约束解释风险资产的相对价格；便利解释最安全、最可抵押的那一层为什么有负的携带。</p><p>后课默认：杠杆与保证金约束破坏共同切点，CAPM 的线性是无约束加总的结论。偏离的截面形状是理论许可，实证换 <a href="/quant/capm">/quant/capm</a>。不重写限价簿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同切点依赖自由借贷；资金约束让市场组合不再人人有效。</li><li>约束乘子进入 \\(m\\)，高资金占用资产的期望超额偏离 \\(\\beta\\lambda_m\\)。</li><li>这是均衡扭曲，不是本栏的横截面检验。</li><li>出处：Black, <em>Journal of Business</em> 1972；Brunnermeier–Pedersen；Frazzini and Pedersen, <em>JFE</em> 2014（理论节）。</li></ul>',10))])}const f=i(m,[["render",B]]);export{P as __pageData,f as default};
